var $jscomp = $jscomp || {};
$jscomp.scope = {};
$jscomp.createTemplateTagFirstArg = function (e) { return e.raw = e };
$jscomp.createTemplateTagFirstArgWithRaw = function (e, t) { return e.raw = t, e };
var BLOCKED_TIME = "hot_blocker_blocked_time",
    BLOCKED_FORE = "hot_blocker_block_minutes",
    FAIL_COUNTER = "hot_blocker_counter",
    $block = document.getElementById("block");

function incrementCounter(e) {
    var t, o;
    return e = null != (t = e.getAttribute("block-time")) ? t : 5,
        t = null != (o = getCookieOrNull(FAIL_COUNTER)) ? o : 0,
        t = parseInt(t) + 1,
        setCookie(FAIL_COUNTER, t, e),
        t;
}

function checkFailsCount(e, t) {
    var o, n;
    t < (null != (o = e.getAttribute("try-count")) ? o : 5) || (
        o = null != (n = e.getAttribute("block-time")) ? n : 5,
        n = timeStamp(),
        setCookie(BLOCKED_TIME, n, o),
        setCookie(BLOCKED_FORE, o, o),
        redirectToBlockPage()
    );
}

function resetCounter() {
    setCookie(BLOCKED_TIME, "", 0);
    setCookie(FAIL_COUNTER, "", 0);
}

function redirectToBlockPage() {
    try {
        document.documentElement.classList.add("is-blocked-mode");
        document.body.classList.add("is-blocked-mode");
        var bNav = document.getElementById("bottomNav");
        if (bNav) bNav.style.setProperty("display", "none", "important");
    } catch(err) {}

    if (null != $block) {
        showParentElement($loginSubmit, $block);
        initCountDown(document.querySelector("span[count-down-span]"));
    }
}

function checkIsBlocked() {
    return null != getCookieOrNull(BLOCKED_TIME) && (redirectToBlockPage(), !0);
}

function setCookie(e, t, o) {
    var n = new Date;
    n.setTime(n.getTime() + 6e4 * o);
    o = "expires=" + n.toUTCString();
    document.cookie = e + "=" + t + ";" + o + ";path=/";
}

function getCookieOrNull(e) {
    var t = null;
    return document.cookie.split(";").forEach((function (o) {
        if ((o = o.trim().split("="))[0] === e) return t = o[1], !0;
    })), t;
}

function timeStamp() {
    return Math.floor((new Date).getTime());
}

function initCountDown(e) {
    var t = getCookieOrNull(BLOCKED_TIME);
    if (null === t) {
        showLoginPage();
        hideBlockPage();
    } else {
        var o = 6e4 * getCookieOrNull(BLOCKED_FORE) + parseInt(t);
        var updateTimer = function () {
            var curr = timeStamp();
            curr = o - curr;
            if (e) {
                e.innerHTML = Math.floor(curr % 36e5 / 6e4) + " دقائق و " + Math.floor(curr % 6e4 / 1e3) + " ثانية";
            }
            if (0 > curr) {
                clearInterval(n);
                showLoginPage();
                hideBlockPage();
            }
        };
        updateTimer();
        var n = setInterval(updateTimer, 1e3);
    }
}

function hideBlockPage() {
    try {
        document.documentElement.classList.remove("is-blocked-mode");
        document.body.classList.remove("is-blocked-mode");
        var bNav = document.getElementById("bottomNav");
        if (bNav) bNav.style.removeProperty("display");
    } catch(err) {}

    if (null != $block) {
        $block.style.display = "none";
        $block.classList.add("inactive");
        $block.classList.remove("active");
    }
}

document.addEventListener("DOMContentLoaded", (function () {
    checkIsBlocked();
}), !1);
